import { render, screen, waitFor } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import { describe, it, expect, vi, beforeEach } from 'vitest';
import { axe, toHaveNoViolations } from 'jest-axe';
import { Checkout } from './Checkout';

expect.extend(toHaveNoViolations);

// BOOM! The mocks emerge from the flames!
const mockProcessPayment = vi.fn();
const mockClearCart = vi.fn();
const mockItems = [
  { id: '1', name: 'Holy Grail', price: 999.99 },
  { id: '2', name: 'Killer Rabbit Repellent', price: 49.99 }
];

vi.mock('./CartContext', () => ({
  useCart: () => ({ items: mockItems, total: 1049.98, clearCart: mockClearCart })
}));

vi.mock('./PaymentContext', () => ({
  usePayment: () => ({ processPayment: mockProcessPayment })
}));

describe('Checkout - THE CAVE OF CAERBANNOG!', () => {
  const user = userEvent.setup();

  beforeEach(() => {
    vi.clearAllMocks();
    mockProcessPayment.mockResolvedValue({ orderId: 'NI-12345' });
  });

  // HAPPY PATH - Follow... but BEWARE!
  describe('Complete checkout flow', () => {
    it('navigates through all steps to confirmation', async () => {
      render(<Checkout />);

      // Shipping - The first TRIAL!
      await user.type(screen.getByLabelText(/street address/i), '123 Camelot Lane');
      await user.type(screen.getByLabelText(/city/i), 'Camelot');
      await user.selectOptions(screen.getByLabelText(/state/i), 'CA');
      await user.type(screen.getByLabelText(/zip code/i), '90210');
      await user.click(screen.getByRole('button', { name: /continue to payment/i }));

      // Payment - The SECOND trial! *explosions*
      await user.type(screen.getByLabelText(/card number/i), '4111111111111111');
      await user.type(screen.getByLabelText(/expiry/i), '12/25');
      await user.type(screen.getByLabelText(/cvv/i), '123');
      await user.type(screen.getByLabelText(/name on card/i), 'King Arthur');
      await user.click(screen.getByRole('button', { name: /review order/i }));

      // Review - BEHOLD your choices!
      expect(screen.getByText(/holy grail/i)).toBeInTheDocument();
      await user.click(screen.getByRole('button', { name: /place order/i }));

      // Confirmation - BOOM! SUCCESS!
      await waitFor(() => {
        expect(screen.getByText(/order confirmed/i)).toBeInTheDocument();
        expect(screen.getByText(/NI-12345/i)).toBeInTheDocument();
      });
    });
  });

  // VALIDATION - The killer rabbit AWAITS!
  describe('Form validation', () => {
    it('shows shipping errors for empty fields', async () => {
      render(<Checkout />);
      await user.click(screen.getByRole('button', { name: /continue to payment/i }));

      expect(screen.getByText(/street address is required/i)).toBeInTheDocument();
      expect(screen.getByText(/city is required/i)).toBeInTheDocument();
    });

    it('validates ZIP code format - I WARNED YOU!', async () => {
      render(<Checkout />);
      await user.type(screen.getByLabelText(/zip code/i), 'DOOM');
      await user.click(screen.getByRole('button', { name: /continue to payment/i }));

      expect(screen.getByText(/valid zip code required/i)).toBeInTheDocument();
    });
  });

  // EDGE CASES - Death awaits with NASTY BIG POINTY TEETH!
  describe('Edge cases', () => {
    it('displays empty cart message', () => {
      vi.mocked(require('./CartContext').useCart).mockReturnValue({
        items: [], total: 0, clearCart: mockClearCart
      });
      render(<Checkout />);

      expect(screen.getByRole('alert')).toHaveTextContent(/cart is empty/i);
    });
  });

  // ACCESSIBILITY - Even ENCHANTMENT must be accessible!
  it('has no accessibility violations - BOOM!', async () => {
    const { container } = render(<Checkout />);
    expect(await axe(container)).toHaveNoViolations();
  });
});
